 689→FString UBridgeComponent::BuildQuestionJson()
 690→{
 691→    // Build JSON representation for backward-compatible delegates
 692→    TSharedPtr<FJsonObject> JsonObj = MakeShared<FJsonObject>();
 693→    JsonObj->SetStringField(TEXT("type"), TEXT("question"));
 694→    JsonObj->SetNumberField(TEXT("index"), CurrentQuestion.Index);
 695→    JsonObj->SetNumberField(TEXT("total"), CurrentQuestion.Total);
 696→    JsonObj->SetStringField(TEXT("id"), CurrentQuestion.QuestionId);
 697→    JsonObj->SetStringField(TEXT("text"), CurrentQuestion.Text);
 698→    JsonObj->SetStringField(TEXT("scene"), CurrentQuestion.Scene);
 699→
 700→    TArray<TSharedPtr<FJsonValue>> OptionsArray;
 701→    for (int32 i = 0; i < CurrentQuestion.OptionLabels.Num(); ++i)
 702→    {
 703→        TSharedPtr<FJsonObject> OptionObj = MakeShared<FJsonObject>();
 704→        OptionObj->SetNumberField(TEXT("index"), i);
 705→        OptionObj->SetStringField(TEXT("label"), CurrentQuestion.OptionLabels[i]);
 706→        OptionObj->SetStringField(TEXT("direction"), CurrentQuestion.OptionDirections[i]);
 707→        OptionsArray.Add(MakeShared<FJsonValueObject>(OptionObj));
 708→    }
 709→    JsonObj->SetArrayField(TEXT("options"), OptionsArray);
 710→
 711→    FString OutputString;
 712→    TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&OutputString);
 713→    FJsonSerializer::Serialize(JsonObj.ToSharedRef(), Writer);
 714→    return OutputString;
