            QuestionWidget->ShowQuestion(CurrentQuestion);
            UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] QuestionWidget visibility: %d, IsInViewport: %d"),
                (int32)QuestionWidget->GetVisibility(), QuestionWidget->IsInViewport());
        }
        else
        {
            UE_LOG(LogTemp, Warning, TEXT("[TranslatorsHUD] QuestionWidget is NULL!"));
        }

        // Show question screen
        ShowQuestionScreen();

        // Debug: show question as on-screen message (bypasses UMG)
        if (GEngine)
        {
            GEngine->AddOnScreenDebugMessage(1, 30.0f, FColor::Green,
                FString::Printf(TEXT("Q%d: %s"), CurrentQuestion.Index + 1, *CurrentQuestion.Text));
            for (int32 i = 0; i < CurrentQuestion.OptionLabels.Num(); i++)
            {
                GEngine->AddOnScreenDebugMessage(10 + i, 30.0f, FColor::Yellow,
                    FString::Printf(TEXT("  [%d] %s"), i + 1, *CurrentQuestion.OptionLabels[i]));
            }
        }

        UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] Displaying question %d/%d: %s"),
            CurrentQuestion.Index + 1, CurrentQuestion.Total, *CurrentQuestion.QuestionId);

        // Log visibility state after ShowQuestionScreen
        UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] After ShowQuestionScreen - Connecting: %d, Question: %d, Finale: %d"),
            ConnectingWidget ? (int32)ConnectingWidget->GetVisibility() : -1,
            QuestionWidget ? (int32)QuestionWidget->GetVisibility() : -1,
            FinaleWidget ? (int32)FinaleWidget->GetVisibility() : -1);
    }
}


void ATranslatorsHUD::OnTransitionReceived(const FString& Direction, const FString& NextScene)
{
    UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] Transition: %s -> %s"), *Direction, *NextScene);

    // Could trigger transition animation here
    // For now, just log it

    // Update progress if question widget exists
    if (QuestionWidget)
    {
        QuestionWidget->UpdateProgress(CurrentQuestion.Index + 2, TotalQuestions);
    }
}


void ATranslatorsHUD::OnFinaleReceived(const FString& UsdPath)
{
    UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] Finale! USD path: %s"), *UsdPath);

    bIsComplete = true;

    // Update finale widget with USD path if it's a UW_FinaleScreen
    UW_FinaleScreen* FinaleScreen = Cast<UW_FinaleScreen>(FinaleWidget);
    if (FinaleScreen)
    {
        FinaleScreen->SetUsdPath(UsdPath);
    }

    // Show finale screen
    ShowFinaleScreen(TEXT("Your cognitive profile is complete."));
}


void ATranslatorsHUD::Tick(float DeltaSeconds)
{
    Super::Tick(DeltaSeconds);
    HandleKeyInput();
}


void ATranslatorsHUD::HandleKeyInput()
{
    // Only process when question is visible and not already answered
    if (!QuestionWidget || QuestionWidget->GetVisibility() != ESlateVisibility::Visible)
    {
        return;
    }
    if (QuestionWidget->GetSelectedOptionIndex() != -1)
    {
        return;  // Already answered
    }

    APlayerController* PC = GetOwningPlayerController();
    if (!PC)
    {
        return;
    }

    // Check number keys 1, 2, 3
    if (PC->WasInputKeyJustPressed(EKeys::One) || PC->WasInputKeyJustPressed(EKeys::NumPadOne))
    {
        OnAnswerSelected(0);
    }
    else if (PC->WasInputKeyJustPressed(EKeys::Two) || PC->WasInputKeyJustPressed(EKeys::NumPadTwo))
    {
        OnAnswerSelected(1);
    }
    else if (PC->WasInputKeyJustPressed(EKeys::Three) || PC->WasInputKeyJustPressed(EKeys::NumPadThree))
    {
        OnAnswerSelected(2);
    }
}


void ATranslatorsHUD::OnAnswerSelected(int32 OptionIndex)
{
    // Calculate response time
    float ResponseTimeMs = (GetWorld()->GetTimeSeconds() - QuestionStartTime) * 1000.0f;

    UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] Answer selected: option %d (%.0fms)"),
        OptionIndex, ResponseTimeMs);

    // Send answer to bridge
    if (BridgeComponent)
    {
        BridgeComponent->SendAnswer(CurrentQuestion.QuestionId, OptionIndex, ResponseTimeMs);
    }
}

