 17→
 18→
 19→ATranslatorsHUD::ATranslatorsHUD()
 20→{
 21→    // Default configuration
 22→    bIsBridgeConnected = false;
 23→    bIsComplete = false;
 24→    TotalQuestions = 8;
 25→}
 26→
 27→
 28→void ATranslatorsHUD::BeginPlay()
 29→{
 30→    Super::BeginPlay();
 31→
 32→    UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] BeginPlay - Initializing..."));
 33→
 34→    // Find BridgeComponent
 35→    BridgeComponent = FindBridgeComponent();
 36→
 37→    if (BridgeComponent)
 38→    {
 39→        UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] Found BridgeComponent - binding events"));
 40→
 41→        // Bind to bridge events (FIXED order - ThinkingMachines compliant)
 42→        BridgeComponent->OnBridgeReady.AddDynamic(this, &ATranslatorsHUD::OnBridgeReady);
 43→        BridgeComponent->OnQuestionReceived.AddDynamic(this, &ATranslatorsHUD::OnQuestionReceived);
 44→        BridgeComponent->OnTransitionReceived.AddDynamic(this, &ATranslatorsHUD::OnTransitionReceived);
 45→        BridgeComponent->OnFinaleReceived.AddDynamic(this, &ATranslatorsHUD::OnFinaleReceived);
 46→    }
 47→    else
 48→    {
 49→        UE_LOG(LogTemp, Warning, TEXT("[TranslatorsHUD] BridgeComponent not found in level!"));
 50→    }
 51→
 52→    // Create UI widgets
 53→    CreateWidgets();
 54→
 55→    // Show connecting screen initially
 56→    ShowConnectingScreen();
 57→
 58→    // Check if bridge already processed state before we subscribed
 59→    if (BridgeComponent)
 60→    {
 61→        if (BridgeComponent->IsBridgeConnected())
 62→        {
 63→            // Bridge already got "ready" - catch up
 64→            OnBridgeReady(TotalQuestions);
 65→        }
 66→
 67→        FTranslatorsQuestion Q = BridgeComponent->GetCurrentQuestion();
 68→        if (!Q.QuestionId.IsEmpty())
 69→        {
 70→            // Bridge already has a question loaded - display it
 71→            UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] Catching up - bridge already has question: %s"), *Q.QuestionId);
 72→            CurrentQuestion = Q;
 73→            QuestionStartTime = GetWorld()->GetTimeSeconds();
 74→            if (QuestionWidget)
 75→            {
 76→                QuestionWidget->ShowQuestion(CurrentQuestion);
 77→            }
 78→            ShowQuestionScreen();
 79→        }
 80→    }
 81→}
 82→
 83→
 84→void ATranslatorsHUD::EndPlay(const EEndPlayReason::Type EndPlayReason)
 85→{
 86→    // Unbind events
 87→    if (BridgeComponent)
 88→    {
 89→        BridgeComponent->OnBridgeReady.RemoveAll(this);
 90→        BridgeComponent->OnQuestionReceived.RemoveAll(this);
 91→        BridgeComponent->OnTransitionReceived.RemoveAll(this);
 92→        BridgeComponent->OnFinaleReceived.RemoveAll(this);
 93→    }
 94→
 95→    // Clean up widgets
 96→    if (QuestionWidget)
 97→    {
 98→        QuestionWidget->OnAnswerSelected.RemoveAll(this);
 99→        QuestionWidget->RemoveFromParent();
100→    }
101→    if (ConnectingWidget)
102→    {
103→        ConnectingWidget->RemoveFromParent();
104→    }
105→    if (FinaleWidget)
106→    {
107→        FinaleWidget->RemoveFromParent();
108→    }
109→
110→    Super::EndPlay(EndPlayReason);
111→}
112→
113→
114→UBridgeComponent* ATranslatorsHUD::FindBridgeComponent()
115→{
116→    // Search all actors for one with BridgeComponent
117→    TArray<AActor*> AllActors;
118→    UGameplayStatics::GetAllActorsOfClass(GetWorld(), AActor::StaticClass(), AllActors);
119→
120→    for (AActor* Actor : AllActors)
121→    {
122→        UBridgeComponent* Bridge = Actor->FindComponentByClass<UBridgeComponent>();
123→        if (Bridge)
124→        {
125→            return Bridge;
126→        }
127→    }
128→
129→    // Fallback: spawn a dedicated actor with BridgeComponent
130→    UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] No BridgeComponent found - spawning BridgeActor"));
131→    UWorld* World = GetWorld();
132→    if (World)
133→    {
134→        FActorSpawnParameters SpawnParams;
135→        SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
136→        AActor* BridgeActor = World->SpawnActor<AActor>(AActor::StaticClass(), FVector::ZeroVector, FRotator::ZeroRotator, SpawnParams);
137→        if (BridgeActor)
138→        {
139→            UBridgeComponent* Bridge = NewObject<UBridgeComponent>(BridgeActor, TEXT("BridgeComponent"));
140→            Bridge->bVerboseLogging = true;
141→            BridgeActor->AddInstanceComponent(Bridge);
142→            Bridge->RegisterComponent();
143→            return Bridge;
144→        }
145→    }
146→
147→    return nullptr;
148→}
