178→        QuestionWidget = CreateWidget<UW_QuestionDisplay>(PC, UW_QuestionDisplay::StaticClass());
179→        if (QuestionWidget)
180→        {
181→            QuestionWidget->AddToViewport(10);
182→            QuestionWidget->SetVisibility(ESlateVisibility::Hidden);
183→            QuestionWidget->OnAnswerSelected.AddDynamic(this, &ATranslatorsHUD::OnAnswerSelected);
184→        }
