 32→void UBridgeComponent::BeginPlay()
 33→{
 34→    Super::BeginPlay();
 35→
 36→    BridgeLog(TEXT("========================================"));
 37→    BridgeLog(TEXT("TRANSLATORS BRIDGE COMPONENT v2.0.0"));
 38→    BridgeLog(TEXT("USD-native communication with JSON fallback"));
 39→    BridgeLog(FString::Printf(TEXT("Bridge Path: %s"), *BridgePath));
 40→    BridgeLog(FString::Printf(TEXT("Resolved state.json: %s"), *GetBridgeFilePath(TEXT("state.json"))));
 41→    BridgeLog(TEXT("========================================"));
 42→
 43→    // Ensure bridge directory exists
 44→    IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
 45→    if (!PlatformFile.DirectoryExists(*BridgePath))
 46→    {
 47→        PlatformFile.CreateDirectory(*BridgePath);
 48→        BridgeLog(FString::Printf(TEXT("Created bridge directory: %s"), *BridgePath));
 49→    }
 50→
 51→    SetupFileWatcher();
 52→
 53→    // Check for existing state files (Claude Code may have started first)
 54→    // Prefer USD over JSON
 55→    FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 56→    FString JsonFilePath = GetBridgeFilePath(TEXT("state.json"));
 57→
 58→    if (PlatformFile.FileExists(*UsdFilePath))
 59→    {
 60→        BridgeLog(TEXT("Found existing bridge_state.usda - processing..."));
 61→        ProcessStateFile();
 62→    }
 63→    else if (PlatformFile.FileExists(*JsonFilePath))
 64→    {
 65→        BridgeLog(TEXT("Found existing state.json - processing..."));
 66→        ProcessStateFile();
 67→    }
 68→}
