 81→void UBridgeComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
 82→{
 83→    Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
 84→
 85→    // Polling fallback for non-editor builds
 86→    if (bUsePolling)
 87→    {
 88→        PollTimer += DeltaTime;
 89→        if (PollTimer >= PollInterval)
 90→        {
 91→            PollTimer = 0.0f;
 92→
 93→            FString StateFilePath = GetBridgeFilePath(TEXT("state.json"));
 94→            IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
 95→
 96→            if (PlatformFile.FileExists(*StateFilePath))
 97→            {
 98→                FDateTime ModTime = PlatformFile.GetTimeStamp(*StateFilePath);
 99→                if (ModTime > LastStateFileTime)
100→                {

100→                {
101→                    LastStateFileTime = ModTime;
102→                    bStateChangePending = true;
103→                    TimeSinceLastStateChange = 0.0f;
104→                }
105→            }
106→        }
107→    }
108→
109→    // Debounced state file processing
110→    if (bStateChangePending)
111→    {
112→        TimeSinceLastStateChange += DeltaTime;
113→        if (TimeSinceLastStateChange >= DebounceTime)
114→        {
115→            bStateChangePending = false;
116→            ProcessStateFile();
117→        }
118→    }
119→
120→    // Debounced USD file processing
121→    if (bUsdChangePending)
122→    {
123→        TimeSinceLastUsdChange += DeltaTime;
124→        if (TimeSinceLastUsdChange >= DebounceTime)
125→        {
126→            bUsdChangePending = false;
127→            OnUsdFileChanged();
128→        }
129→    }
130→}
