508→bool UBridgeComponent::ProcessBridgeStateUsda()
509→{
510→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
511→    FString Content;
512→
513→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
514→    {
515→        return false;
516→    }
517→
518→    // Parse sync_status variant
519→    FString SyncStatus = ParseUsdaVariant(Content, TEXT("sync_status"));
520→    FString MessageType = ParseUsdaVariant(Content, TEXT("message_type"));
521→
522→    if (bVerboseLogging)
523→    {
524→        BridgeLog(FString::Printf(TEXT("USD sync_status=%s, message_type=%s"), *SyncStatus, *MessageType));
525→    }
526→
527→    // Route based on message type
528→    if (MessageType == TEXT("ready"))
529→    {
530→        HandleUsdaReadyState(Content);
531→    }
532→    else if (MessageType == TEXT("question") && SyncStatus == TEXT("question_pending"))
533→    {
534→        HandleUsdaQuestionState(Content);
535→    }
536→    else if (MessageType == TEXT("transition"))
537→    {
538→        HandleUsdaTransitionState(Content);
539→    }
540→    else if (MessageType == TEXT("finale"))
541→    {
542→        HandleUsdaFinaleState(Content);
543→    }
544→
545→    return true;
546→}
